#!/usr/bin/env node
/**
 * stencil-assemble: curated stencil JSON -> generated TypeScript.
 *
 * The final, deterministic stage of the stencil pipeline (design/format/stencil-pipeline.md),
 * run after the curation swarm has edited the per-set JSON (labels, keywords, categories,
 * dropping degenerate shapes). It renders two generated files from the union of all inputs:
 *
 *   - packages/editor/src/render/stencils.generated.ts  — the geometry REGISTRY, `id -> d`
 *     (the normalized SVG path). The engine's `render/shape` looks a `stencil=<id>` node up
 *     here, so palette thumbnail and canvas are drawn by the same data.
 *   - packages/app/src/shapes/stencils.generated.ts      — the catalogue `ShapeDef[]` the
 *     shapes panel presents (spread into `shapes/catalog`).
 *
 * Both are GENERATED — never hand-edit; re-run this instead. Inputs are `*.stencils.json`
 * from `stencil-import.mjs`. No dependencies (Node >=18, ESM).
 *
 * After assembling, run `prettier --write` on the two generated files — the CI format gate
 * checks them like any other source.
 *
 * Usage:  node stencil-assemble.mjs <a.stencils.json> [b.stencils.json ...]
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const EDITOR_OUT = resolve(HERE, '../src/render/stencils.generated.ts')
const APP_OUT = resolve(HERE, '../../app/src/shapes/stencils.generated.ts')

const inputs = process.argv.slice(2)
if (inputs.length === 0) {
  console.error('usage: node stencil-assemble.mjs <a.stencils.json> [b.stencils.json ...]')
  process.exit(2)
}

const shapes = []
const seen = new Set()
for (const path of inputs) {
  const { shapes: sets } = JSON.parse(readFileSync(path, 'utf8'))
  for (const s of sets) {
    if (seen.has(s.id)) continue // union is dedup-by-id; first input wins
    seen.add(s.id)
    shapes.push(s)
  }
}
shapes.sort((a, b) => a.id.localeCompare(b.id))

const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
const banner = (tool) =>
  `/* GENERATED by packages/editor/tools/${tool} — do not edit. Re-run the stencil\n` +
  ` * pipeline to regenerate (design/format/stencil-pipeline.md).\n` +
  ` *\n` +
  ` * Shape geometry derived from draw.io (https://github.com/jgraph/drawio) shape stencils,\n` +
  ` * (c) JGraph Ltd and contributors, licensed CC BY 4.0\n` +
  ` * (https://creativecommons.org/licenses/by/4.0/), converted to normalized paths / TikZ\n` +
  ` * option presets. See packages/app/THIRD_PARTY_NOTICES.md. */\n`

// --- editor registry: id -> normalized SVG path 'd' -------------------------
const registry =
  banner('stencil-assemble.mjs') +
  '\n/** Normalized SVG path (`d`) per stencil id, in a [0,1]x[0,1] y-down box. */\n' +
  'export const STENCILS: Record<string, string> = {\n' +
  shapes.map((s) => `  ${q(s.id)}: ${q(s.d)},`).join('\n') +
  '\n}\n'
mkdirSync(dirname(EDITOR_OUT), { recursive: true })
writeFileSync(EDITOR_OUT, registry)

// --- app catalogue: ShapeDef[] ---------------------------------------------
const defs =
  banner('stencil-assemble.mjs') +
  "\nimport type { ShapeDef } from './catalog'\n" +
  '\n/** The imported stencil library — spread into `SHAPES` in `shapes/catalog`. */\n' +
  'export const STENCIL_SHAPES: ShapeDef[] = [\n' +
  shapes
    .map(
      (s) =>
        `  {\n` +
        `    id: ${q(s.id)},\n` +
        `    label: ${q(s.label)},\n` +
        `    category: ${q(s.category)},\n` +
        `    keywords: [${s.keywords.map(q).join(', ')}],\n` +
        `    options: [${s.options.map(q).join(', ')}],\n` +
        `    size: { width: ${s.size.width}, height: ${s.size.height} },\n` +
        `    body: '',\n` +
        `  },`,
    )
    .join('\n') +
  '\n]\n'
mkdirSync(dirname(APP_OUT), { recursive: true })
writeFileSync(APP_OUT, defs)

console.error(
  `assembled ${shapes.length} stencils -> ${EDITOR_OUT.split('/packages/').pop()} + ` +
    `${APP_OUT.split('/packages/').pop()}`,
)
